import{a as e,i as t,r as n,t as r}from"./app-BKUFyoHP.js";var i=JSON.parse(`{"path":"/experience.html","title":"Work Experience","lang":"en-US","frontmatter":{},"git":{"updatedTime":1786469929000,"contributors":[{"name":"ashwani","username":"ashwani","email":"ashwanipandey679@gmail.com","commits":1,"url":"https://github.com/ashwani"}],"changelog":[{"hash":"2590e3637c6d21e6a31f107b35c17814726bfb8b","time":1786469929000,"email":"ashwanipandey679@gmail.com","author":"ashwani","message":"Added code."}]},"filePathRelative":"experience.md"}`),a={name:`experience.md`};function o(r,i,a,o,s,c){return e(),n(`div`,null,[...i[0]||=[t(`<h1 id="work-experience" tabindex="-1"><a class="header-anchor" href="#work-experience"><span>Work Experience</span></a></h1><p>Details of my professional journey in software engineering.</p><hr><h2 id="associate-software-engineer" tabindex="-1"><a class="header-anchor" href="#associate-software-engineer"><span>Associate Software Engineer</span></a></h2><p><strong>Webkul Software Pvt. Ltd.</strong> | <em>January 2026 – Present</em><br><em>Role Focus: Magento 2 marketplace extension development &amp; maintenance</em></p><ul><li><strong>Custom Extensions</strong>: Developed custom Magento 2 extensions and extended the <em>Webkul Marketplace Extension</em> with business-specific features and custom functionalities while ensuring Hyvä theme compatibility.</li><li><strong>Security &amp; Performance</strong>: Implemented a custom rate-limiting mechanism using Magento Cache and Session management to prevent duplicate requests, improve request handling, and enhance application stability.</li><li><strong>Query &amp; Execution Optimization</strong>: Reduced API response times by <strong>60-70%</strong> by implementing asynchronous processing with Magento Cron Jobs and batch processing, alongside optimizing SQL queries for database scalability.</li><li><strong>Automated Testing</strong>: Wrote Playwright test scripts from scratch to validate end-to-end user journeys and module functionality for each extension.</li><li><strong>Technical Writing</strong>: Utilized AI agents to generate clean integration guides and developer documentation.</li></ul><hr><h2 id="php-developer" tabindex="-1"><a class="header-anchor" href="#php-developer"><span>PHP Developer</span></a></h2><p><strong>Rudra Innovative Software</strong> | <em>July 2025 – December 2025</em><br><em>Role Focus: Asset tracking &amp; IoT integrations</em></p><ul><li><strong>Platform Contribution</strong>: Contributed to backend and frontend development for <em>AlerTrax</em>, a GPS/IoT asset-tracking platform, working across Laravel and Vue.js.</li><li><strong>Collaboration</strong>: Collaborated with design and frontend teams in an Agile environment, maintaining clean code practices and ensuring smooth feature integration.</li></ul><hr><h2 id="web-developer" tabindex="-1"><a class="header-anchor" href="#web-developer"><span>Web Developer</span></a></h2><p><strong>BrainGrid Technology Pvt. Ltd.</strong> | <em>July 2024 – July 2025</em><br><em>Role Focus: E-commerce &amp; Laravel full-stack support</em></p><ul><li><strong>Tech Stack</strong>: Worked with both Laravel and Magento 2, gaining hands-on, production-level experience in both ecosystems.</li><li><strong>Client Solutions</strong>: Maintained existing client sites, resolved incoming bug tickets, and implemented custom features based on client requirements.</li><li><strong>Best Practices</strong>: Followed MVC architecture pattern, Git version control, and modular styling patterns under senior mentorship.</li></ul><hr><h2 id="software-developer-intern" tabindex="-1"><a class="header-anchor" href="#software-developer-intern"><span>Software Developer Intern</span></a></h2><p><strong>Code Brew Labs</strong> | <em>December 2023 – July 2024</em><br><em>Role Focus: Support &amp; Debugging</em></p><ul><li><strong>Bug Resolution</strong>: Resolved bugs and improved application stability as part of the support team, using Laravel debugging tools.</li><li><strong>Mentorship</strong>: Gained knowledge in MVC structure, Git version control, and Laravel development standards under senior developers.</li></ul>`,18)]])}var s=r(a,[[`render`,o]]);export{i as _pageData,s as default};